window.docContents[165].resolve({"/Basic-Types/Bitvectors/#Lean-__________________--Basic-Types--Bitvectors--API-Reference--Arithmetic":{"contents":"These operators treat bitvectors as numbers.\nSome operations are signed, while others are unsigned.\nBecause bitvectors are understood as two's complement numbers, addition, subtraction and multiplication coincide for the signed and unsigned interpretations.\n\nAdds two bitvectors. This can be interpreted as either signed or unsigned addition modulo 2^n.\nUsually accessed via the + operator.SMT-LIB name: bvadd.\n\nSubtracts one bitvector from another. This can be interpreted as either signed or unsigned subtraction\nmodulo 2^n. Usually accessed via the - operator.\n\nMultiplies two bitvectors. This can be interpreted as either signed or unsigned multiplication\nmodulo 2^n. Usually accessed via the * operator.SMT-LIB name: bvmul.\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Bitvectors\u0009API Reference","header":"20.5.5.8. Arithmetic","id":"/Basic-Types/Bitvectors/#Lean-__________________--Basic-Types--Bitvectors--API-Reference--Arithmetic"},"/Basic-Types/Floating-Point-Numbers/#Float-api":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Floating-Point Numbers","header":"20.6.3. API Reference","id":"/Basic-Types/Floating-Point-Numbers/#Float-api"},"/Functors___-Monads-and--do--Notation/Syntax/#The-Lean-Language-Reference--Functors___-Monads-and--do--Notation--Syntax--Infix-Operators--Functors":{"contents":"\n\nFunctor.map 有两个中缀运算符。\n\n函子运算符g <$> x 是 Functor.map g x 的简写。x <&> g 是 Functor.map g x 的简写。\n\n\n\n","context":"Lean 中文参考手册\u0009函子、单子与  do  记法\u0009语法\u0009中缀运算符","header":"18.3.1.1. 函子","id":"/Functors___-Monads-and--do--Notation/Syntax/#The-Lean-Language-Reference--Functors___-Monads-and--do--Notation--Syntax--Infix-Operators--Functors"},"/Introduction/#introduction":{"contents":"这是Lean语言参考手册。\n它旨在对Lean进行全面而精确的描述，是Lean用户查找详细信息的参考资料，而不是给新用户的入门教程。\n如需其他文档，请参阅Lean文档总览(英文) 或 lean中文文档。\n本手册涵盖Lean 4.34.0-rc1版本。\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册","header":"1. 简介","id":"/Introduction/#introduction"},"/releases/v4.27.0/#Lean-__________________--Release-Notes--Lean-4___27___0-_LPAR_2026-01-24_RPAR_--Highlights--Performance-Gains":{"contents":"This release includes many performance improvements, notably:\n\n* #11162 reduces the memory consumption of the language server (the\n  watchdog process in particular). In Mathlib, it reduces memory\n  consumption by about 1GB.* #11507 optimizes the filesystem accesses during importing for a ~3% win\n  on Linux, potentially more on other platforms.\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.27.0 (2026-01-24)\u0009Highlights","header":"Performance Gains","id":"/releases/v4.27.0/#Lean-__________________--Release-Notes--Lean-4___27___0-_LPAR_2026-01-24_RPAR_--Highlights--Performance-Gains"},"/releases/v4.28.0/#Lean-__________________--Release-Notes--Lean-4___28___0-_LPAR_2026-02-17_RPAR_--Highlights--Library-Highlights--Bitvectors":{"contents":"* #11257 adds the\n  definition of BitVec.cpop, aka popcount.* #11767 introduces\n  two induction principles for bitvectors, based on the concat and\n  cons operations.\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.28.0 (2026-02-17)\u0009Highlights\u0009Library Highlights","header":"Bitvectors","id":"/releases/v4.28.0/#Lean-__________________--Release-Notes--Lean-4___28___0-_LPAR_2026-02-17_RPAR_--Highlights--Library-Highlights--Bitvectors"}});